-- Esquema inicial generado desde las entidades JPA, F3
create table game (turn integer, created timestamp(6) not null, finish_date timestamp(6), id bigint generated by default as identity, location varchar(255), nation varchar(255) check ((nation in ('WATER','AIR','FIRE','EARTH'))), primary key (id));
create table game_player (score integer, game_id bigint, id bigint generated by default as identity, join_date timestamp(6), player_id bigint, emote varchar(255), primary key (id));
create table player (id bigint generated by default as identity, email varchar(255), name varchar(255), nation varchar(255) check ((nation in ('WATER','AIR','FIRE','EARTH'))), password varchar(255), primary key (id));
create table player_roles (roles smallint check ((roles between 0 and 2)), player_id bigint not null);
create table salvo (turn integer not null, game_player_id bigint, id bigint generated by default as identity, primary key (id));
create table salvo_locations (salvo_id bigint not null, locations varchar(255));
create table ship (game_player_id bigint, id bigint generated by default as identity, type varchar(255) check ((type in ('CARRIER','BATTLESHIP','SUBMARINE','DESTROYER','PATROL_BOAT','NONAME'))), primary key (id));
create table ship_locations (ship_id bigint not null, locations varchar(255));
create table ship_salvos_impacted (ship_id bigint not null, salvos_impacted varchar(255));
